tool_input.command:
hops feature-group create --name features13a256 --version 1 --description "Derived feature table for transactions with USD conversion, weekend flag, and 7-day rolling sum." --primary-key row_id --event-time event_time --online-enabled true --features row_id:STRING,account_id:STRING,event_time:BIGINT,amount_usd:DOUBLE,is_weekend:INT,amount_7d:DOUBLE --transformations """
{
  "amount_usd": {
    "type": "js",
    "script": "function transform(row) {
      const fxRates = {\"EUR\": 1.09, \"SEK\": 0.095, \"GBP\": 1.27, \"USD\": 1.0};
      const fxRate = fxRates[row.currency] || 1.0;
      return row.amount * fxRate;
    }"
  },
  "is_weekend": {
    "type": "js",
    "script": "function transform(row) {
      const eventTime = new Date(row.event_time);
      const dayOfWeek = eventTime.getUTCDay();
      return (dayOfWeek === 6 || dayOfWeek === 0) ? 1 : 0;
    }"
  },
  "amount_7d": {
    "type": "window_aggregation",
    "window": "7d",
    "aggregation": "sum",
    "feature": "amount",
    "group_by": ["account_id"]
  }
}
""" --input "data/transactions.csv" --input "data/fx_rates.csv"

